                questionText: '为了探究并联电路的电流规律，小薇设计了如图1所示的电路进行实验。\n(1)在连接电路时，开关应处于_______状态。\n(2)闭合开关后，观察到电流表指针反偏，错误原因是______________。\n(3)小薇先将电流表接在L~1~所在的支路上，闭合开关后，看到灯L~2~发光，但灯L~1~不发光，电流表的示数为零，电路可能存在的故障是______________。\n(4)排除故障后，她测出了L~1~、L~2~支路和干路电流分别为$I_1$、$I_2$和$I$，电流表示数如图3中甲、乙、丙所示，可读出：$I_1=0.8$A，$I_2$=_______A，$I$=_______A。根据测量结果，在误差允许范围内你认为并联电路中干路电流和各支路电流的关系是_______（写出关系式即可）。\n(5)为了验证结论的普遍性，小薇可以采用的方法是______________。\n(6)小敏连接了如图2所示的实物连接图，此时电流表测的是通过_______（选填"L~1~""L~2~"或"干路"）的电流。若要测灯L~2~中的电流，请你在图上只改动一根导线，完成电路的连接_______。（在需改动的导线上打"×"，再画出重新连接后的导线）',
                questionImages: ['https://pub-3827e3697a0b44428ab555d41c8d38f3.r2.dev/experiment/question/15-7-1.webp'],
                //answerText: '【答案】(1)断开 (2)电流表正负接线柱接反了 (3)L~1~断路 (4)0.2 1 $I=I_1+I_2$ (5)换用不同规格的灯泡多次实验 (6)L~2~ 见解析<br>【详解】（1）连接电路时开关应断开。（2）电流表指针反偏说明正负接线柱接反了。（3）L~2~发光说明电路通路，L~1~不发光且电流表无示数，说明L~1~断路。（4）甲图$I_1=0.8$A，乙图$I_2=0.2$A，丙图$I=1$A，并联电路干路电流等于各支路电流之和。（5）换用不同规格的灯泡进行多次实验。（6）电流表在干路上测干路电流，测L~2~电流需将电流表与L~2~串联。'
